"proposal": {
  "capability": "deployment.set-probes",
  "target": {"group": "apps", "kind": "Deployment", "namespace": "edge", "name": "api-gateway", "uid": "uid-deployment-api-gateway"},
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 20,
      "timeoutSeconds": 5
    },
    "readiness": {
      "initialDelaySeconds": 5,
      "timeoutSeconds": 3
    }
  },
  "expected_effect": "The liveness probe will wait longer before timing out, allowing the application to start and respond to probes before being killed.",
  "rationale": "The pod was killed during startup (killed_during_startup: true) with liveness probe failures. The current timeoutSeconds (1) is too short for the application to respond. Increasing these values aligns with the observed startup duration (1m2s) and prevents premature termination.",
